const response = $input.first().json;
let xml = response?.choices?.[0]?.message?.content ?? '';
xml = String(xml).trim();
xml = xml.replace(/^```xml\s*/i, '');
xml = xml.replace(/^```\s*/i, '');
xml = xml.replace(/\s*```$/i, '');
xml = xml.trim();

const chargeOpeningPattern = /<charge_estimee(?:\s|>)/i;
const chargeClosingPattern = /<\/charge_estimee>/i;
const candidateXmlChargeEstimeePresent = chargeOpeningPattern.test(xml);
let chargeEstimeeNormalizationApplied = false;

if (!candidateXmlChargeEstimeePresent && !chargeClosingPattern.test(xml)) {
  const riskPattern = /(<risque_sous_dimensionnement\b[^>]*>)([\s\S]*?)(<\/risque_sous_dimensionnement>)/i;
  if (riskPattern.test(xml)) {
    xml = xml.replace(riskPattern, '$1$2\n<charge_estimee>Non trouvé</charge_estimee>\n$3');
    chargeEstimeeNormalizationApplied = true;
  }
}

const markdownSource = $('Read Markdown as Text').first().json;
const markdown = markdownSource.markdown || markdownSource.text || '';

return [{
  json: {
    xml,
    markdown,
    candidate_xml_charge_estimee_present: candidateXmlChargeEstimeePresent,
    charge_estimee_normalization_applied: chargeEstimeeNormalizationApplied,
    provider: 'gemini',
    llm_model: 'gemini-3.6-flash',
  },
}];

const item = $input.first();
const xml = String(item.json.xml || '').trim();
const markdown = String(item.json.markdown || '').trim();
const extractionFields = ["reference_officielle", "intitule_mission", "client_maitre_ouvrage", "pays", "zone_execution", "projet_rattachement", "source_financement", "credit_financement", "secteur", "nature_prestation", "type_procedure", "methode_selection", "type_proposition", "type_contrat", "date_emission", "date_limite_depot", "langue_offre", "ponderation_technique_financiere", "note_technique_minimale", "duree_totale", "volume_hommes_mois", "nombre_profils_experts", "phases_mission", "livrables_principaux", "nombre_livrables_structurants", "profils_cles", "disciplines_techniques", "nombre_sites", "contraintes_site", "outils_methodes", "moyens_materiels", "exigences_es", "normes_referentiels", "points_techniques_structurants"];
const evaluationFields = ["complexite_technique", "difficulte_terrain", "risque_sous_dimensionnement"];
const controlChildren = ['champs_non_trouves', 'incoherences', 'a_verifier'];

let successReady = true;
let errorStage = null;
let errorCode = null;
let errorMessage = null;
let missingElement = null;

const hasOpeningTag = (name) => new RegExp(`<${name}(?:\\s|>)`, 'i').test(xml);
const hasClosingTag = (name) => new RegExp(`</${name}>`, 'i').test(xml);
const hasClosingOrSelfClosingTag = (name) => hasClosingTag(name) || new RegExp(`<${name}\\b[^>]*/>`, 'i').test(xml);
const hasAttributeOnOpeningTag = (name, attribute) =>
  new RegExp(`<${name}\\b[^>]*\\b${attribute}=`, 'i').test(xml);
const sectionBody = (name) => {
  const match = xml.match(new RegExp(`<${name}\\b[^>]*>([\\s\\S]*?)</${name}>`, 'i'));
  return match ? match[1] : null;
};
const fail = (code, message, element = null) => {
  successReady = false;
  errorStage = 'XML';
  errorCode = code;
  errorMessage = message;
  missingElement = element;
};

if (!markdown) {
  fail('MARKDOWN_EMPTY', 'Le markdown retourne par Marker est vide.');
} else if (!xml) {
  fail('XML_EMPTY', 'Le XML retourne par Gemini est vide.');
} else if (!hasOpeningTag('fiche_projet')) {
  fail('XML_INVALID_ROOT', 'Le XML retourne par Gemini ne contient pas la racine fiche_projet attendue.', 'fiche_projet');
} else if (!hasClosingTag('fiche_projet')) {
  fail('XML_INCOMPLETE', 'Le XML retourne par Gemini est incomplet : balise fermante </fiche_projet> manquante.', 'fiche_projet');
} else if (!hasOpeningTag('reference_interne') || !hasClosingTag('reference_interne')) {
  fail('XML_SCHEMA_INVALID', 'Le XML retourne par Gemini ne contient pas l\'element obligatoire <reference_interne>.', 'reference_interne');
} else if (!hasOpeningTag('extraction') || !hasClosingTag('extraction')) {
  fail('XML_SCHEMA_INVALID', 'Le XML retourne par Gemini ne contient pas la section obligatoire <extraction>.', 'extraction');
} else if (!hasOpeningTag('evaluation') || !hasClosingTag('evaluation')) {
  fail('XML_SCHEMA_INVALID', 'Le XML retourne par Gemini ne contient pas la section obligatoire <evaluation>.', 'evaluation');
} else if (!hasOpeningTag('controle') || !hasClosingTag('controle')) {
  fail('XML_SCHEMA_INVALID', 'Le XML retourne par Gemini ne contient pas la section obligatoire <controle>.', 'controle');
}

if (successReady) {
  for (const field of extractionFields) {
    if (!hasOpeningTag(field)) {
      fail('XML_SCHEMA_INVALID', `Le XML retourne par Gemini ne contient pas l'element obligatoire <${field}>.`, field);
      break;
    }
    if (!hasClosingTag(field)) {
      fail('XML_INCOMPLETE', `Le XML retourne par Gemini est incomplet : balise fermante </${field}> manquante.`, field);
      break;
    }
    if (!hasAttributeOnOpeningTag(field, 'source')) {
      fail('XML_SCHEMA_INVALID', `Le XML retourne par Gemini ne contient pas l'attribut source obligatoire sur <${field}>.`, field);
      break;
    }
  }
}

if (successReady) {
  for (const field of evaluationFields) {
    if (!hasOpeningTag(field)) {
      fail('XML_SCHEMA_INVALID', `Le XML retourne par Gemini ne contient pas l'element d'evaluation obligatoire <${field}>.`, field);
      break;
    }
    if (!hasClosingTag(field)) {
      fail('XML_INCOMPLETE', `Le XML retourne par Gemini est incomplet : balise fermante </${field}> manquante.`, field);
      break;
    }
    if (!hasAttributeOnOpeningTag(field, 'note')) {
      fail('XML_SCHEMA_INVALID', `Le XML retourne par Gemini ne contient pas l'attribut note obligatoire sur <${field}>.`, field);
      break;
    }

    const evaluationBody = sectionBody(field);
    if (!evaluationBody) {
      fail('XML_INCOMPLETE', `Le XML retourne par Gemini est incomplet : contenu de <${field}> indisponible.`, field);
      break;
    }
    if (!/<justification(?:\s|>)/i.test(evaluationBody) || !/<\/justification>/i.test(evaluationBody)) {
      fail('XML_SCHEMA_INVALID', `Le XML retourne par Gemini ne contient pas l'element <justification> obligatoire dans <${field}>.`, field);
      break;
    }
    if (field === 'risque_sous_dimensionnement' &&
      (!/<charge_estimee(?:\s|>)/i.test(evaluationBody) || !/<\/charge_estimee>/i.test(evaluationBody))) {
      fail('XML_SCHEMA_INVALID', 'Le XML retourne par Gemini ne contient pas l\'element <charge_estimee> obligatoire dans <risque_sous_dimensionnement>.', 'charge_estimee');
      break;
    }
  }
}

if (successReady) {
  for (const field of controlChildren) {
    if (!hasOpeningTag(field)) {
      fail('XML_SCHEMA_INVALID', `Le XML retourne par Gemini ne contient pas l'element obligatoire <${field}> dans <controle>.`, field);
      break;
    }
    if (!hasClosingOrSelfClosingTag(field)) {
      fail('XML_INCOMPLETE', `Le XML canonique est incomplet : balise fermante ou auto-fermante pour <${field}> manquante dans <controle>.`, field);
      break;
    }
  }
}

return [{
  json: {
    ...item.json,
    success_ready: successReady,
    error_stage: errorStage,
    error_code: errorCode,
    error_message: errorMessage,
    missing_required_element: missingElement,
  },
}];

const context = $('Build CDC Extraction Context').first().json;
const getNodeJson = (nodeName) => {
  try {
    return $(nodeName).first()?.json ?? null;
  } catch {
    return null;
  }
};
const item = $input.first();
const pdfInfo = getNodeJson('Validate Source PDF Binary') ?? {};
const markerStats = getNodeJson('Build CDC Extraction Context') ?? {};
const finishedAt = new Date().toISOString();
const durationMs = Math.max(0, Date.parse(finishedAt) - Date.parse(context.started_at));
const payload = {
  contract_version: context.contract_version,
  processing_job_id: context.processing_job_id,
  appel_offre_id: context.appel_offre_id,
  code_interne: context.code_interne,
  correlation_id: context.correlation_id,
  execution_id: context.execution_id,
  status: 'COMPLETED',
  started_at: context.started_at,
  finished_at: finishedAt,
  duration_ms: durationMs,
  metadata: {
    provider: item.json.provider ?? context.cdc_ai_provider,
    llm_model: item.json.llm_model ?? context.llm_model,
    embedding_model: item.json.embedding_model ?? null,
    validation: item.json.local_validation ?? null,
    marker_poll_count: markerStats.marker_poll_count ?? null,
    marker_elapsed_ms: markerStats.marker_elapsed_ms ?? null,
    pdf_size_bytes: pdfInfo.pdf_size_bytes ?? context.pdf_size_bytes ?? null,
  },
  result: {
    markdown: item.json.markdown,
    xml: item.json.xml,
  },
};

const rawBody = JSON.stringify(payload);

return [{
  json: {
    callback_sign_request: {
      callback_url: context.callback_url,
      contract_version: context.contract_version,
      callback_timestamp: new Date().toISOString(),
      callback_raw_body: rawBody,
      terminal_status: 'COMPLETED',
    },
  },
}];

const context=$('Select CDC AI Provider').first().json;
const finishedAt=new Date().toISOString();
const durationMs=Math.max(0,Date.parse(finishedAt)-Date.parse(context.started_at));
const provider=context.cdc_ai_provider;
const input=$input.first().json;
const payload={contract_version:context.contract_version,processing_job_id:context.processing_job_id,appel_offre_id:context.appel_offre_id,code_interne:context.code_interne,correlation_id:context.correlation_id,execution_id:context.execution_id,status:'FAILED',started_at:context.started_at,finished_at:finishedAt,duration_ms:durationMs,metadata:{provider,llm_model:context.llm_model},error:{stage:'LLM',code:provider==='local'?'LOCAL_FICHE_GENERATION_FAILED':'LLM_REQUEST_FAILED',message:String(input.error?.message||input.message||(provider==='local'?'Local Fiche generation failed.':'Gemini request failed.')),retryable:true,provider}};
return [{json:{callback_sign_request:{callback_url:context.callback_url,contract_version:context.contract_version,callback_timestamp:new Date().toISOString(),callback_raw_body:JSON.stringify(payload),terminal_status:'FAILED'}}}];

const context = $('Build CDC Extraction Context').first().json;
const getNodeJson = (nodeName) => {
  try {
    return $(nodeName).first()?.json ?? null;
  } catch {
    return null;
  }
};
const item = $input.first();
const selectedProvider = getNodeJson('Select CDC AI Provider')?.cdc_ai_provider ?? 'local';
const markerStats = getNodeJson('Build CDC Extraction Context') ?? {};
const finishedAt = new Date().toISOString();
const durationMs = Math.max(0, Date.parse(finishedAt) - Date.parse(context.started_at));
const payload = {
  contract_version: context.contract_version,
  processing_job_id: context.processing_job_id,
  appel_offre_id: context.appel_offre_id,
  code_interne: context.code_interne,
  correlation_id: context.correlation_id,
  execution_id: context.execution_id,
  status: 'FAILED',
  started_at: context.started_at,
  finished_at: finishedAt,
  duration_ms: durationMs,
  metadata: {
    provider: selectedProvider,
    llm_model: getNodeJson('Select CDC AI Provider')?.llm_model ?? context.llm_model,
    marker_poll_count: markerStats.marker_poll_count ?? null,
    marker_elapsed_ms: markerStats.marker_elapsed_ms ?? null,
  },
  error: {
    stage: String($input.first().json.error_stage || 'UNKNOWN'),
    code: String($input.first().json.error_code || 'VALIDATION_FAILED'),
    message: String($input.first().json.error_message || 'Validation de sortie echouee.'),
    retryable: false,
    provider: selectedProvider,
  },
};

const rawBody = JSON.stringify(payload);

return [{
  json: {
    callback_sign_request: {
      callback_url: context.callback_url,
      contract_version: context.contract_version,
      callback_timestamp: new Date().toISOString(),
      callback_raw_body: rawBody,
      terminal_status: 'FAILED',
    },
  },
}];

const item = $input.first();
const signed = item.json?.body && typeof item.json.body === 'object'
  ? item.json.body
  : item.json;

return [{
  json: {
    callback_url: signed.callback_url,
    contract_version: signed.contract_version,
    callback_timestamp: signed.callback_timestamp,
    callback_signature: signed.callback_signature,
    callback_raw_body: signed.callback_raw_body,
    terminal_status: signed.terminal_status,
  },
}];

const item=$input.first(); const body=item.json.body??item.json??{}; const headers=item.json.headers??{}; const env=typeof $env==='object'&&$env?$env:{}; const h=(n)=>String(headers[n]||headers[n.toLowerCase()]||'').trim(); const fail=(m,c,s=400)=>[{json:{launch_valid:false,response_status:s,response_body:JSON.stringify({error:m,code:c})}}];
if(!env.N8N_WEBHOOK_TOKEN) return fail('N8N_WEBHOOK_TOKEN absent.','WORKFLOW_CONFIGURATION_ERROR',500); if(h('authorization')!=='Bearer '+env.N8N_WEBHOOK_TOKEN) return fail('Jeton invalide.','UNAUTHORIZED',401);
const required=['contract_version','processing_job_id','appel_offre_id','code_interne','correlation_id','source_processing_job_id','markdown_document_id','markdown_path','markdown_content_hash','callback_url','requested_at']; for(const k of required) if(typeof body[k]!=='string'||!body[k].trim()) return fail('Champ invalide: '+k,'INVALID_LAUNCH_PAYLOAD');
if(h('idempotency-key')!==body.correlation_id+':cdc-extraction') return fail('Idempotency-Key invalide.','INVALID_IDEMPOTENCY_KEY'); if(body.contract_version!==String(env.N8N_CONTRACT_VERSION||'1.0')) return fail('Version invalide.','INVALID_CONTRACT_VERSION');
return [{json:{...body,markdown_byte_size:Number(body.markdown_byte_size),launch_valid:true}}];

const item=$input.first().json;
const env=typeof $env==='object'&&$env?$env:{};
const bool=(name,fallback=false)=>{ const raw=String(env[name]??'').trim().toLowerCase(); if(!raw)return fallback; if(raw==='true')return true; if(raw==='false')return false; throw new Error(name+' doit valoir exactement true ou false.'); };
let provider=String(env.CDC_AI_PROVIDER||'local').trim().toLowerCase();
let routeAllowed=['local','gemini'].includes(provider);
let errorCode=routeAllowed?item.error_code:'AI_PROVIDER_INVALID';
let errorMessage=routeAllowed?item.error_message:'CDC_AI_PROVIDER doit valoir local ou gemini.';
try {
  const confidential=bool('CONFIDENTIAL_MODE',false);
  if(provider==='gemini') {
    const enabled=bool('EXTERNAL_AI_COMPARISON_ENABLED',false);
    const authorized=new Set(String(env.EXTERNAL_AI_AUTHORIZED_CDC_IDS||'').split(',').map(v=>v.trim()).filter(Boolean));
    if(confidential){ routeAllowed=false; errorCode='CONFIDENTIAL_EXTERNAL_PROVIDER_BLOCKED'; errorMessage='Le mode confidentiel interdit tout appel CDC externe.'; }
    else if(!enabled){ routeAllowed=false; errorCode='EXTERNAL_AI_COMPARISON_DISABLED'; errorMessage='La comparaison externe CDC exige une activation explicite.'; }
    else if(!authorized.has(String(item.code_interne))){ routeAllowed=false; errorCode='EXTERNAL_AI_CDC_NOT_AUTHORIZED'; errorMessage='Ce CDC n est pas autorise pour une comparaison externe.'; }
  }
} catch(error) { routeAllowed=false; errorCode='AI_POLICY_CONFIGURATION_INVALID'; errorMessage=String(error.message||error); }
return [{json:{...item,cdc_ai_provider:provider,llm_model:provider==='local'?String(env.LOCAL_FICHE_MODEL||'qwen3:14b'):'gemini-3.6-flash',route_allowed:routeAllowed,error_stage:routeAllowed?item.error_stage:'LLM',error_code:errorCode,error_message:errorMessage}}];
